mapper.select:
SELECT *
FROM plt_credential_grant
WHERE tenant_id = #{query.tenantId}
  AND credential_id = #{query.credentialId}
  AND grantee_type = #{query.granteeType}
  AND grantee_id = #{query.granteeId}
  AND device_id = #{query.deviceId}
  AND protocol = #{query.protocol}
  AND command_template_id = #{query.commandTemplateId}
  AND status = 'ACTIVE'
  AND (expires_at IS NULL OR expires_at > #{query.effectiveAt})
  AND deleted = b'0'
ORDER BY id DESC
